<script>
(function () {
  var section = document.getElementById('catalogue');
  if (!section) { return; }
  var tabs = section.querySelectorAll('.tl-cat-tab');
  var items = section.querySelectorAll('.tl-item');
  var countEl = document.getElementById('tl-cat-count');
  var current = 'all';

  function updateCount() {
    var visible = 0;
    for (var i = 0; i < items.length; i++) {
      var el = items[i];
      if (el.offsetParent !== null || getComputedStyle(el).display !== 'none') { visible++; }
    }
    if (countEl) {
      countEl.textContent = 'Showing ' + visible + (visible === 1 ? ' product' : ' products');
    }
  }

  function setCategory(cat) {
    current = cat || 'all';
    for (var i = 0; i < items.length; i++) {
      var match = current === 'all' || items[i].getAttribute('data-category') === current;
      items[i].classList.toggle('tl-hide-cat', !match);
    }
    for (var j = 0; j < tabs.length; j++) {
      var active = tabs[j].getAttribute('data-category') === current;
      tabs[j].classList.toggle('is-active', active);
      tabs[j].setAttribute('aria-pressed', active ? 'true' : 'false');
    }
    updateCount();
    document.dispatchEvent(new CustomEvent('tl:category-change', { detail: { category: current } }));
  }

  for (var k = 0; k < tabs.length; k++) {
    tabs[k].addEventListener('click', function () {
      setCategory(this.getAttribute('data-category'));
    });
  }

  window.tlCatalogue = {
    setCategory: setCategory,
    getCategory: function () { return current; },
    refreshCount: updateCount
  };
})();
</script>
