<script>
(function () {
  var panel = document.getElementById('filters');
  var grid = document.getElementById('tl-product-grid');
  var sizeSel = document.getElementById('tl-filter-size');
  var priceSel = document.getElementById('tl-filter-price');
  var clearBtn = document.getElementById('tl-filter-clear');
  var statusEl = document.getElementById('tl-filter-status');
  if (!panel || !grid || !sizeSel || !priceSel || !clearBtn || !statusEl) { return; }

  var items = grid.querySelectorAll('.tl-item');

  // Dock the controls above the product count, inside the catalogue, if it exists.
  var anchor = document.getElementById('tl-cat-count');
  if (anchor && anchor.parentNode) {
    anchor.parentNode.insertBefore(panel, anchor);
    panel.classList.add('is-docked');
  }

  function priceRange() {
    var v = priceSel.value;
    if (!v) { return { min: 0, max: Infinity }; }
    var parts = v.split('-');
    return {
      min: parts[0] ? Number(parts[0]) : 0,
      max: parts[1] ? Number(parts[1]) : Infinity
    };
  }

  function updateStatus() {
    var visible = 0;
    for (var i = 0; i < items.length; i++) {
      if (!items[i].classList.contains('tl-hide-cat') && !items[i].classList.contains('tl-hide-filter')) { visible++; }
    }
    var active = sizeSel.value !== '' || priceSel.value !== '';
    statusEl.textContent = (active && visible === 0)
      ? 'No products match these filters. Clear filters to see all products.'
      : '';
  }

  function apply() {
    var size = sizeSel.value;
    var range = priceRange();
    for (var i = 0; i < items.length; i++) {
      var sizes = (items[i].getAttribute('data-sizes') || '').split(',');
      var price = Number(items[i].getAttribute('data-price'));
      var okSize = size === '' || sizes.indexOf(size) !== -1;
      var okPrice = price >= range.min && price <= range.max;
      items[i].classList.toggle('tl-hide-filter', !(okSize && okPrice));
    }
    if (window.tlCatalogue && typeof window.tlCatalogue.refreshCount === 'function') {
      window.tlCatalogue.refreshCount();
    }
    updateStatus();
  }

  function clearAll() {
    sizeSel.value = '';
    priceSel.value = '';
    apply();
  }

  sizeSel.addEventListener('change', apply);
  priceSel.addEventListener('change', apply);
  clearBtn.addEventListener('click', clearAll);
  document.addEventListener('tl:category-change', updateStatus);

  window.tlFilters = {
    clear: clearAll,
    getState: function () { return { size: sizeSel.value, price: priceSel.value }; }
  };

  apply();
})();
