<script>
(function () {
  var NUMBER = '910000011111';

  function productName(card) {
    var holder = card.closest('[data-name]');
    var name = holder ? holder.getAttribute('data-name') : '';
    if (!name) {
      var h = card.querySelector('h3');
      name = h ? h.textContent.trim() : '';
    }
    return name;
  }

  function addButtons() {
    var cards = document.querySelectorAll('#catalogue .tl-product, #newarrivals .tl-arrival');
    for (var i = 0; i < cards.length; i++) {
      var card = cards[i];
      if (card.querySelector('.tl-order-btn')) { continue; }
      var name = productName(card);
      if (!name) { continue; }
      var message = 'Hi Thread & Loom, I would like to order: ' + name;
      var link = document.createElement('a');
      link.className = 'j2-btn tl-order-btn';
      link.href = 'https://wa.me/' + NUMBER + '?text=' + encodeURIComponent(message);
      link.target = '_blank';
      link.rel = 'noopener';
      link.textContent = 'Order on WhatsApp';
      link.setAttribute('aria-label', 'Order ' + name + ' on WhatsApp');
      card.appendChild(link);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', addButtons);
  } else {
    addButtons();
  }

  window.tlOrder = { refresh: addButtons };
})();
</script>
